#!/usr/bin/env python3
"""Write hand.scad from hand/left-hand.json: the few measured values the
low-profile layout uses, so OpenSCAD can read them. Run from anywhere:

    python3 lowpro/hand_from_json.py

hand/left-hand.json stays the only place these numbers are edited."""
import json
import math
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
hand = json.loads((ROOT / "hand" / "left-hand.json").read_text())
FINGERS = ["index", "middle", "ring", "pinky"]


def vec(v, n=3):
    return "[" + ", ".join(f"{x:.1f}" for x in v[:n]) + "]"


lines = [
    "// GENERATED by lowpro/hand_from_json.py from hand/left-hand.json. Do not edit.",
    "// The measured left hand in the layout axes (reads as the right half):",
    "// origin at the middle fingertip's resting print, +X toward the pinky, +Y away",
    "// from you, +Z up from the flat surface. Millimetres and degrees.",
    "",
    "HAND_FINGERS = " + json.dumps(FINGERS) + ";",
    "// Where each fingertip rested on the flat paper.",
    "HAND_REST = [" + ", ".join(vec(hand["measured"]["fingertip_rest"][f]) for f in FINGERS) + "];",
    "// The finger's direction in plan, degrees from +Y toward +X (PIP seen from the MCP).",
    "HAND_HEADING = ["
    + ", ".join(f"{hand['fingers'][f]['rest']['heading_deg']:.1f}" for f in FINGERS)
    + "];",
    "// Resting joint centres, for the reach radius: [MCP, PIP, DIP] per finger.",
    "HAND_JOINTS = ["
    + ", ".join(
        "[" + ", ".join(vec(hand["fingers"][f]["rest"]["joints"][j]) for j in ["mcp", "pip", "dip"]) + "]"
        for f in FINGERS
    )
    + "];",
    "// The thumb's pad prints: 1 rest, 2 swept in, 3 swept out, 4 pulled back, 5 curled in.",
    "HAND_THUMB_PRINTS = ["
    + ", ".join(vec(hand["measured"]["thumb_prints"][k]) for k in "12345")
    + "];",
    "// The circle (centre, radius) prints 1 to 4 lie on, in plan.",
]
arc = hand["thumb"]["arc_through_prints_1_to_4"]
lines += [
    f"HAND_THUMB_ARC_CENTRE = {vec(arc['centre'], 2)};",
    f"HAND_THUMB_ARC_RADIUS = {arc['radius_mm']:.1f};",
    "// The assumed thumb base joint (CMC), for orientation only.",
    f"HAND_THUMB_CMC = {vec(hand['thumb']['assumed_cmc']['cmc'])};",
    "",
]
(ROOT / "lowpro" / "hand.scad").write_text("\n".join(lines))
print("wrote lowpro/hand.scad")
